impl Solution {
    pub fn max_k_segments_sum(nums: Vec<i64>, m: usize, k: usize) -> i128 {
        let n = nums.len();
        let mut max_sum = 0i128;

        if k == 0 {
            return 0;
        }

        if m > n {
            return 0;
        }

        let mut starts: Vec<usize> = Vec::new();

        fn solve(
            nums: &Vec<i64>,
            m: usize,
            k: usize,
            start_index: usize,
            current_sum: i128,
            starts: &mut Vec<usize>,
            max_sum: &mut i128,
        ) {
            if k == 0 {
                *max_sum = (*max_sum).max(current_sum);
                return;
            }

            if start_index >= nums.len() {
                return;
            }

            for i in start_index..nums.len() - m + 1 {
                starts.push(i);
                let mut segment_sum = 0i128;
                for j in 0..m {
                    segment_sum += nums[i + j] as i128;
                }
                solve(
                    nums,
                    m,
                    k - 1,
                    i + m,
                    current_sum + segment_sum,
                    starts,
                    max_sum,
                );
                starts.pop();
            }
        }

        solve(&nums, m, k, 0, 0, &mut starts, &mut max_sum);

        max_sum
    }
}

